// Listener recipient key, content grants and access requests (Music v1 formats).
//
// * The X25519 recipient key is generated by WebCrypto as NON-EXTRACTABLE and
//   stored as a CryptoKey in this origin's IndexedDB, bound to the HWC agent
//   it was created for. Only its public half is ever read or sent.
// * Grants are stored exactly as the artist signed them (the content key is
//   still wrapped to the recipient key). Unwrapped content keys exist only as
//   non-extractable AES-GCM CryptoKeys in memory during playback.
// * Every grant is verified with the native rules (security/v1.js) against
//   the artist key from the listener's own Holochain cell, this browser's
//   agent and the exact signed manifest before it is stored or used.

import * as v1 from '../../security/v1.js';

const DB = 'holochain-music-web-v1';
const KEYS = 'recipient-keys';
const GRANTS = 'grants';

function openDb(indexedDB = globalThis.indexedDB) {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(DB, 1);
    req.onupgradeneeded = () => {
      req.result.createObjectStore(KEYS);
      req.result.createObjectStore(GRANTS);
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

function tx(db, store, mode, fn) {
  return new Promise((resolve, reject) => {
    const t = db.transaction(store, mode);
    const s = t.objectStore(store);
    let result;
    Promise.resolve(fn(s)).then(r => { result = r; }, reject);
    t.oncomplete = () => resolve(result);
    t.onerror = () => reject(t.error);
  });
}

const req = r => new Promise((resolve, reject) => { r.onsuccess = () => resolve(r.result); r.onerror = () => reject(r.error); });

export const RequestOutcome = Object.freeze({
  /** The artist's conductor stored the request (call_remote returned Ok). */
  SENT: 'sent',
  /** This browser conductor cannot make Holochain remote calls. Nothing sent. */
  TRANSPORT_UNSUPPORTED: 'transport-unsupported',
  /** The artist's node could not be reached. Nothing was delivered. */
  UNREACHABLE: 'unreachable',
  /** The artist's node refused the delivery (rate limit, invalid). Not a decision. */
  REFUSED: 'refused',
  FAILED: 'failed',
});

/** Classify a send_access_request failure without ever inventing a decision. */
export function classifyRequestError(message) {
  const m = String(message ?? '');
  if (/No ConductorCell in target|Unsupported cell target|call_remote transport unavailable/i.test(m)) return RequestOutcome.TRANSPORT_UNSUPPORTED;
  if (/recipient refused|recipient is busy|Unauthorized|BadCapGrant|BadNonce/i.test(m)) return RequestOutcome.REFUSED;
  if (/unreachable|timed out|not connected|no url for peer|disconnected|NetworkError|offline/i.test(m)) return RequestOutcome.UNREACHABLE;
  return RequestOutcome.FAILED;
}

/**
 * Local record of requests this browser identity sent (public facts only:
 * file, kind, time). Used to show "awaiting the artist's decision"; the
 * artist's decision itself only ever comes from a verified grant.
 */
export class RequestLog {
  constructor(storage = globalThis.localStorage) { this.storage = storage; }
  key(agent) { return `hm-requests:${agent}`; }
  all(agent) {
    try { return JSON.parse(this.storage?.getItem(this.key(agent)) ?? '{}') || {}; } catch { return {}; }
  }
  get(agent, fileId) { return this.all(agent)[fileId] ?? null; }
  record(agent, fileId, kind, at = Math.floor(Date.now() / 1000)) {
    const all = this.all(agent);
    all[fileId] = { kind, sent_at: at };
    try { this.storage?.setItem(this.key(agent), JSON.stringify(all)); } catch { /* private mode: in-page only */ }
    return all[fileId];
  }
}

export class GrantStore {
  constructor({ indexedDB } = {}) {
    this._db = openDb(indexedDB);
  }

  /** The agent's recipient key; created once, never exported. */
  async recipientKey(agent) {
    const db = await this._db;
    const existing = await tx(db, KEYS, 'readonly', s => req(s.get(agent)));
    if (existing?.privateKey?.type === 'private' && existing.privateKey.extractable === false) return existing;
    const created = { ...(await v1.generateRecipientKey()), agent, created_at: Math.floor(Date.now() / 1000) };
    await tx(db, KEYS, 'readwrite', s => req(s.put(created, agent)));
    return created;
  }

  async list(agent) {
    const db = await this._db;
    const all = await tx(db, GRANTS, 'readonly', s => req(s.getAll()));
    return all.filter(g => g.listener_agent === agent);
  }

  async get(agent, fileId) {
    const db = await this._db;
    return tx(db, GRANTS, 'readonly', s => req(s.get(`${agent}:${fileId}`)));
  }

  /**
   * Verify a signed grant for THIS listener and track, then store it.
   * Idempotent for duplicate deliveries; a perpetual licence is never
   * replaced by a time-limited grant.
   */
  async accept(grant, { agent, trusted, via }) {
    const recipient = await this.recipientKey(agent);
    const key = await v1.unwrapContentGrant(grant, {
      trustedArtist: trusted.artistKey, ownerAgent: trusted.artistAgent, listenerAgent: agent,
      recipientPrivate: recipient.privateKey, recipientPublicHex: recipient.publicHex, signedManifest: trusted.manifest,
    });
    const kind = v1.grantKind(grant);
    const id = `${agent}:${trusted.manifestBody.file_id}`;
    const db = await this._db;
    const previous = await tx(db, GRANTS, 'readonly', s => req(s.get(id)));
    const same = previous && JSON.stringify(previous.grant) === JSON.stringify(grant);
    const downgrade = previous?.kind === 'perpetual-personal' && kind !== 'perpetual-personal';
    if (!same && !downgrade) {
      await tx(db, GRANTS, 'readwrite', s => req(s.put({
        listener_agent: agent, owner_agent: trusted.artistAgent, file_id: trusted.manifestBody.file_id,
        manifest_sha256: trusted.digest, kind, grant, received_via: via, verified_at: Math.floor(Date.now() / 1000),
        expires_at: grant.body.expires_at ?? null,
      }, id)));
    }
    return { key, kind, duplicate: Boolean(same), kept_licence: downgrade };
  }

  /** Re-verify a stored grant immediately before playback; returns the content CryptoKey. */
  async contentKey(agent, trusted) {
    const stored = await this.get(agent, trusted.manifestBody.file_id);
    if (!stored) throw new v1.GrantError('no grant for this track: request access from the artist');
    return (await this.accept(stored.grant, { agent, trusted, via: stored.received_via })).key;
  }

  async forget(agent, fileId) {
    const db = await this._db;
    await tx(db, GRANTS, 'readwrite', s => req(s.delete(`${agent}:${fileId}`)));
  }
}

/**
 * Pull grants delivered privately to this listener's own source chain
 * (music_storage.get_inbox_grants) and keep only those that verify.
 * resolveTrusted(owner, fileId) must return the catalogue trust result.
 */
export async function syncInboxGrants({ holochain, store, agent, resolveTrusted }) {
  const rows = await holochain.call('music_storage', 'get_inbox_grants', null);
  const results = [];
  for (const row of Array.isArray(rows) ? rows : []) {
    const b = row?.body;
    try {
      const trusted = await resolveTrusted(b.owner_agent, b.file_id);
      if (!trusted || trusted.artistAgent !== b.owner_agent) continue;
      const grant = JSON.parse(b.grant_json);
      results.push({ file_id: b.file_id, ...(await store.accept(grant, { agent, trusted, via: 'holochain-inbox' })) });
    } catch (e) {
      results.push({ file_id: b?.file_id, error: e.message });
    }
  }
  return results;
}

/**
 * Ask the artist for access using the unchanged Music request format.
 * The Music DNA delivers requests with Holochain `call_remote`, whose
 * provenance authenticates the listener and binds the X25519 key to it.
 * SENT means the artist's own conductor stored the private request; it does
 * NOT mean the artist approved anything.
 */
export async function requestAccess({ holochain, store, agent, track, kind, note = '' }) {
  if (kind !== 'stream' && kind !== 'perpetual-personal') throw new Error('invalid access kind');
  const recipient = await store.recipientKey(agent);
  const request = {
    file_id: track.file_id, manifest_sha256: track.manifest_sha256,
    x25519_public_hex: recipient.publicHex, kind, note: String(note).slice(0, 500),
  };
  const { holoHashBytes } = await import('../../security/bytes.js');
  try {
    await holochain.call('music_storage', 'send_access_request', { owner: holoHashBytes(track.artist_agent), request });
    return { outcome: RequestOutcome.SENT, request };
  } catch (e) {
    return { outcome: classifyRequestError(e.message), error: e.message, request };
  }
}
